set -euo pipefail

BODY=$(cat wiki.markdown)

jq --null-input \
   --arg key "$REDMINE_TOKEN" \
   --arg text "$BODY" \
   --arg comments "Autogenerated from Dependency Dashboard" \
   '{key:$key,wiki_page:{text:$text,comments:$comments}}' > body.json
curl -fsS -X PUT -H "Content-Type: application/json" -d "@body.json" "${RM_URL}/projects/${RM_PROJECT_ID}/wiki/Renovate_${CI_PROJECT_NAME}.json"
